            log.push(json!({ "method": method, "params": params, "result": result }));
        }
        Ok(answer.result)
    }

    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
        decode(&self.scoped_text(method, extra).await?)
    }

